        function handleSigilloKeypress(event, idx) {
            if (event.key === 'Enter') {
                salvaSigillo(idx);
            }
        }
        
        function handleMatricolaKeypress(event, idx) {
            if (event.key === 'Enter') {
                salvaMatricola(idx);
            }
        }
        
        async function salvaSigillo(idx) {
            const card = document.getElementById(`sigillo-card-${idx}`);
            const input = document.getElementById(`sigillo-input-${idx}`);
            const btn = document.getElementById(`sigillo-btn-${idx}`);
            const status = document.getElementById(`sigillo-status-${idx}`);
            
            const sigillo = input.value.trim();
            if (!sigillo) {
                status.className = 'sigilli-card-status visible error';
                status.textContent = 'âš ï¸ Inserisci un codice sigillo';
                return;
            }
            
            const eneltel = card.dataset.eneltel;
            
            // Loading state
            btn.disabled = true;
            input.disabled = true;
            status.className = 'sigilli-card-status visible loading';
            status.textContent = 'â³ Salvataggio...';
            
            try {
                const response = await fetch(`${API_BASE}/api/sigillo/${eneltel}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ sigillo: sigillo })
                });
                
                const result = await response.json();
                
                if (response.ok && result.success) {
                    status.className = 'sigilli-card-status visible success';
                    status.textContent = 'âœ… Sigillo salvato!';
                    card.classList.add('completato');
                    
                    // Mostra il valore salvato con pulsante modifica
                    input.value = sigillo;
                    input.disabled = true;
                    btn.style.display = 'none';
                    
                    // Crea pulsante modifica
                    let editBtn = document.getElementById(`sigillo-edit-${idx}`);
                    if (!editBtn) {
                        editBtn = document.createElement('button');
                        editBtn.id = `sigillo-edit-${idx}`;
                        editBtn.className = 'btn-modifica-sigillo';
                        editBtn.innerHTML = 'âœï¸ Modifica';
                        editBtn.onclick = function() { modificaSigillo(idx); };
                        input.parentNode.appendChild(editBtn);
                    }
                    
                    // RIMUOVI dalla lista dati per preservare lo stato anche dopo cambio filtro
                    const eneltelSalvato = card.dataset.eneltel;
                    sigilliData = sigilliData.filter(c => c.eneltel !== eneltelSalvato);
                    
                    // Aggiorna contatori
                    const remaining = sigilliData.length;
                    document.getElementById('sigilliCount').textContent = `(${remaining} da completare)`;
                    document.getElementById('tabSigilliCount').textContent = remaining;
                    
                    // Focus sul prossimo
                    focusNextInput(card, 'sigillo-input');
                    
                } else {
                    btn.disabled = false;
                    input.disabled = false;
                    status.className = 'sigilli-card-status visible error';
                    status.textContent = 'âŒ ' + (result.error || 'Errore sconosciuto');
                }
            } catch (err) {
                btn.disabled = false;
                input.disabled = false;
                status.className = 'sigilli-card-status visible error';
                status.textContent = 'âŒ Errore di connessione: ' + err.message;
            }
        }
        
