        function apriModalBackup() {
            document.getElementById('backupModal').classList.add('visible');
            caricaListaBackup();
        }
        
        function chiudiModalBackup() {
            document.getElementById('backupModal').classList.remove('visible');
        }
        
        async function caricaListaBackup() {
            const container = document.getElementById('backupLista');
            container.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-secondary);">â³ Caricamento...</div>';
            
            try {
                const resp = await fetch('/api/backup/lista');
                const data = await resp.json();
                
                if (!data.success) {
                    container.innerHTML = '<div class="backup-empty">âŒ ' + (data.error || 'Errore') + '</div>';
                    return;
                }
                
                const backups = data.backups || [];
                
                if (backups.length === 0) {
                    container.innerHTML = '<div class="backup-empty">ðŸ“­ Nessun backup disponibile.<br>VerrÃ  creato automaticamente al prossimo sync.</div>';
                    return;
                }
                
                let html = '';
                for (const b of backups) {
                    const dataFormatted = b.data_backup ? new Date(b.data_backup + 'T00:00:00').toLocaleDateString('it-IT', {
                        weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
                    }) : 'Data sconosciuta';
                    
                    const tsFormatted = b.timestamp ? new Date(b.timestamp).toLocaleString('it-IT') : '';
                    
                    html += `
                        <div class="backup-item">
                            <div class="backup-item-info">
                                <div class="backup-item-date">ðŸ“… ${dataFormatted}</div>
                                <div class="backup-item-meta">
                                    ${b.totale_righe} righe Â· ${b.dimensione_mb} MB Â· ${tsFormatted}
                                </div>
                            </div>
                            <div class="backup-item-actions">
                                <button class="backup-btn-ripristina" onclick="ripristinaBackup('${b.filename}', '${dataFormatted}')">
                                    ðŸ”„ Ripristina
                                </button>
                                <button class="backup-btn-elimina" onclick="eliminaBackup('${b.filename}')">
                                    ðŸ—‘ï¸
                                </button>
                            </div>
                        </div>
                    `;
                }
                
                container.innerHTML = html;
                
            } catch (err) {
                container.innerHTML = '<div class="backup-empty">âŒ Errore di connessione: ' + err.message + '</div>';
            }
        }
        
        function mostraBackupStatus(msg, tipo) {
            const el = document.getElementById('backupStatus');
            el.style.display = 'block';
            el.textContent = msg;
            if (tipo === 'success') {
                el.style.background = 'linear-gradient(135deg, #27ae60 0%, #2ecc71 100%)';
                el.style.color = 'white';
            } else if (tipo === 'error') {
                el.style.background = 'linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)';
                el.style.color = 'white';
            } else {
                el.style.background = 'linear-gradient(135deg, #3498db 0%, #2980b9 100%)';
                el.style.color = 'white';
            }
            // Nascondi dopo 5 secondi
            setTimeout(() => { el.style.display = 'none'; }, 5000);
        }
        
        async function eseguiBackupManuale(forza) {
            mostraBackupStatus('â³ Backup in corso...', 'loading');
            
            try {
                const resp = await fetch('/api/backup/esegui', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ forza: forza })
                });
                const data = await resp.json();
                
                if (data.success) {
                    mostraBackupStatus('âœ… ' + data.message, 'success');
                    caricaListaBackup();
                } else {
                    mostraBackupStatus('âŒ ' + (data.message || data.error), 'error');
                }
            } catch (err) {
                mostraBackupStatus('âŒ Errore: ' + err.message, 'error');
            }
        }
        
        async function ripristinaBackup(filename, dataLabel) {
            const conferma = confirm(
                `âš ï¸ ATTENZIONE: Stai per ripristinare il backup del ${dataLabel}.\n\n` +
                `Questa operazione SOVRASCRIVERÃ€ tutti i dati attuali del FILONE su Google Drive!\n\n` +
                `Sei sicuro di voler procedere?`
            );
            
            if (!conferma) return;
            
            // Doppia conferma per sicurezza
            const conferma2 = confirm(
                `ðŸ”´ ULTIMA CONFERMA\n\n` +
                `Il FILONE attuale verrÃ  COMPLETAMENTE sostituito con il backup del ${dataLabel}.\n\n` +
                `Confermi il ripristino?`
            );
            
            if (!conferma2) return;
            
            mostraBackupStatus('â³ Ripristino in corso... (puÃ² richiedere qualche minuto)', 'loading');
            
            try {
                const resp = await fetch('/api/backup/ripristina', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ filename: filename })
                });
                const data = await resp.json();
                
                if (data.success) {
                    mostraBackupStatus('âœ… ' + data.message, 'success');
                    // Notifica che ci sarÃ  un sync
                    setTimeout(() => {
                        mostraBackupStatus('ðŸ”„ Sync mappa in corso...', 'loading');
                    }, 3000);
                } else {
                    mostraBackupStatus('âŒ ' + (data.message || data.error), 'error');
                }
            } catch (err) {
                mostraBackupStatus('âŒ Errore: ' + err.message, 'error');
            }
        }
        
        async function eliminaBackup(filename) {
            if (!confirm('Vuoi eliminare questo backup?')) return;
            
            try {
                const resp = await fetch('/api/backup/elimina', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ filename: filename })
                });
                const data = await resp.json();
                
                if (data.success) {
                    mostraBackupStatus('ðŸ—‘ï¸ ' + data.message, 'success');
                    caricaListaBackup();
                } else {
                    mostraBackupStatus('âŒ ' + (data.message || data.error), 'error');
                }
            } catch (err) {
                mostraBackupStatus('âŒ Errore: ' + err.message, 'error');
            }
        }
    

